occ={(0,1),(0,2),(0,4),(0,5),*( (1,c) for c in range(6)),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
shapes=[]
for r in range(3):
 for c in range(6):
  square={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if square<=occ: shapes.append((1,square))
  for missing in [(r,c),(r,c+1),(r+1,c),(r+1,c+1)]:
   s=square-{missing}
   if s<=occ: shapes.append((2,s))
sol=[]
def go(rem, picked):
 if not rem:
  sol.append(picked); return
 cell=min(rem)
 for typ,s in shapes:
  if cell in s and s<=rem:
   go(rem-s,picked+[(typ,s)])
go(occ,[])
len(sol), [[(t,sorted(s)) for t,s in x] for x in sol[:10]]
